class EvidenceTests(unittest.TestCase):
    def assess(self, raw=CONTROL, **kwargs):
        return assess(raw,2,FIXTURES[0],identity=kwargs.pop('identity',IDENTITY),**kwargs)
    def reject(self, raw):
        result = self.assess(raw)
        self.assertEqual(result['status'],'FAIL',result)

    def test_complete_cycle_and_remote_evidence(self):
        result = self.assess()
        self.assertEqual(result['status'],'PASS',result)
        self.assertEqual(result['same_object_remote_ack_order'],'PASS')
        self.assertEqual(result['remote_flushes'],1)
        self.assertEqual(result['global_allocator_drift'] if 'global_allocator_drift' in result else 'NOT_RUN','NOT_RUN')

    def test_each_required_record_is_necessary(self):
        lines = CONTROL.splitlines()
        for i,line in enumerate(lines):
            required = line.startswith(('[AE-GRANT]','[AE-MAP]','[AE-UNMAP]','[AE-TLB]','[AE-PMM]','[AE-TERMINAL]','[AE-FRESH]','[AE-USER]'))
            required |= line.startswith('[AE-SNAPSHOT]') and 'event=fresh-request ' not in line
            required |= 'checkpoint=old-call-peer-closed ' in line or 'checkpoint=replacement-old-session-denied ' in line or 'checkpoint=fixture-complete ' in line
            required |= line.startswith('[SCHED] process_reaped') and any('pid='+pid+' ' in line for pid in ('19','39','40','41'))
            if required:
                with self.subTest(line=line):
                    self.reject('\n'.join(lines[:i]+lines[i+1:]))

    def test_metadata_cleanup_does_not_prove_physical_reclamation(self):
        for prefix in ('[AE-PMM]','[AE-UNMAP]','[AE-TLB]'):
            self.reject('\n'.join(l for l in CONTROL.splitlines() if not l.startswith(prefix)))

    def test_exact_identity_and_generation_are_required(self):
        for key in ('frame','issuer','issuer_inc','issuer_vm','caller','caller_inc','caller_vm','endpoint','generation','object'):
            line=next(l for l in CONTROL.splitlines() if l.startswith('[AE-GRANT]') and 'event=selected ' in l)
            value=next(v for v in line.split() if v.startswith(key+'='))
            self.reject(CONTROL.replace(line,line.replace(value,key+'=999'),1))
        self.reject(CONTROL.replace('auth=1','auth=0'))
        self.reject(CONTROL.replace('event=replacement pid=19 inc=31 vm=90','event=replacement pid=19 inc=31 vm=49'))
        self.reject(CONTROL.replace('views=0','views=1'))
        self.reject(CONTROL.replace('event=free','event=retained'))

    def test_remote_ack_requires_handler_witness_and_complete_mask(self):
        ack=next(l for l in CONTROL.splitlines() if 'event=ack-observed ' in l)
        for key in ('produced','request','ack_cpu','targets'):
            value=next(v for v in ack.split() if v.startswith(key+'='))
            self.reject(CONTROL.replace(ack,ack.replace(value,key+'=999'),1))
        self.reject(CONTROL+'\n'+ack)
        self.reject(CONTROL.replace(ack,''))
        self.reject(CONTROL.replace('cpu=0','cpu=-1'))

    def test_zero_targets_cannot_claim_remote_execution(self):
        lines=[]
        for line in CONTROL.splitlines():
            if 'event=ack-observed ' in line: continue
            if line.startswith('[AE-TLB]'): line=re.sub(r'targets=\d+','targets=0',line)
            lines.append(line)
        result=self.assess('\n'.join(lines))
        self.assertEqual(result['status'],'PASS',result)
        self.assertEqual(result['same_object_remote_ack_order'],'BLOCKED')
        self.assertEqual(result['remote_acknowledgements'],0)

    def test_actual_exec_syscall_and_failed_exec_are_required(self):
        self.reject(CONTROL.replace('[SYSCALL] exec: success,','[METHOD] exec: success,'))
        self.reject(CONTROL.replace('[SYSCALL] exec path=/bin/session-racer','[METHOD] exec path=/bin/session-racer'))
        self.reject(CONTROL.replace('[SYSCALL] exec: path not found: /missing-account-exec','[METHOD] failed-exec'))

    def test_duplicate_terminal_order_fault_and_identity_are_rejected(self):
        terminal=next(l for l in CONTROL.splitlines() if l.startswith('[AE-TERMINAL]'))
        self.reject(CONTROL+'\n'+terminal)
        self.reject(CONTROL.replace('event=free object=1','event=free object=1 object=2'))
        self.reject(CONTROL.replace('outcome=PeerClosed(4)','outcome=ReplyDelivered(4)'))
        self.reject(CONTROL+'\nPANIC')
        self.assertEqual(self.assess(identity=None)['status'],'FAIL')
        self.assertEqual(self.assess(failure={'type':'TimeoutError'})['status'],'FAIL')
        lines=CONTROL.splitlines(); i=next(i for i,l in enumerate(lines) if 'event=free ' in l)
        line=lines.pop(i); lines.insert(0,line); self.reject('\n'.join(lines))

    def test_same_guest_cycles_and_missing_cycle_are_distinct(self):
        result=assess_cycles(CYCLES,2,FIXTURES,identity=IDENTITY)
        self.assertEqual(result['status'],'PASS',result)
        self.assertEqual(result['repeated_same_boot_authenticated_cycles'],'PASS')
        self.assertEqual(result['scoped_resource_drift'],'PASS')
        self.assertEqual(result['global_allocator_drift'],'NOT_RUN')
        for raw,fixtures in ((CYCLES,FIXTURES+['missing']),(CYCLES.replace('event=selected grant=2','event=missing grant=2'),FIXTURES),(CYCLES,[FIXTURES[0]]*3)):
            self.assertEqual(assess_cycles(raw,2,fixtures,identity=IDENTITY)['status'],'FAIL')


if __name__ == '__main__':
    unittest.main()
